mapper.select:
SELECT , s.name AS student_name, s.student_no AS student_no, u.real_name AS counselor_name FROM employment_track e LEFT JOIN student s ON e.student_id = s.id LEFT JOIN sys_user u ON e.counselor_id = u.id
AND s.name LIKE CONCAT('%', #{studentName}, '%') AND e.employment_status = #{employmentStatus} AND e.student_id = #{studentId} AND e.counselor_id = #{counselorId}
ORDER BY e.track_date DESC, e.id DESC

mapper.update:
UPDATE employment_track
student_id = #{studentId}, employment_status = #{employmentStatus}, company = #{company}, position = #{position}, salary = #{salary}, city = #{city}, school = #{school}, major = #{major}, track_date = #{trackDate}, remark = #{remark}, counselor_id = #{counselorId},
WHERE id = #{id}
